  ('5a218c54-a17c-5dac-9b46-41d8fe371836', '22222222-2222-2222-2222-22222222221c', 'short', '𝑎3 −𝑏3 = (𝑎−𝑏)(𝑎2 + 𝑎𝑏+ 𝑏2).', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 77, null),
  ('1a096685-c099-50f1-a0ad-74f901cf28e3', '22222222-2222-2222-2222-22222222221c', 'short', '(𝑎+ 𝑏)3 = 𝑎3 + 3𝑎2𝑏+ 3𝑎𝑏2 + 𝑏3.', null, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 30, true, 78, null),
